contexts['def-qsmx-lattice-current-and-limits']='Local charge conservation and a fixed bond orientation define a Hermitian current and its connected Gibbs correlation. This convention also requires a declared order of limits for transport, but asserts no equivalence between a correlation formula and existence of a transport coefficient.'
rows=[]
for b in scope['batches']:
 for r in b['rows']:
  id,c=r['id'],r['case']
  if c.startswith('iff-'):
   assert id in contexts,(id,c)
   rows.append({'batch':b['batch'],'id':id,'case':c,'mode':'template_review','note':contexts[id]})
  else:
   assert (id,c) in notes,(id,c)
   rows.append({'batch':b['batch'],'id':id,'case':c,'mode':'disposition',**notes[(id,c)]})
(base/'boundary-decisions.json').write_text(json.dumps({'reviewer':'/root/qsm_boundary','independent_review':False,'native_transition':False,'rows':rows},indent=2)+'\n')
print('Prepared actual decisions for',len(rows),'flagged rows')
